import { Avatar, Box, Stack, Typography } from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import { Check, PushPin, UsersThree } from "phosphor-react";
import { useDispatch, useSelector } from "react-redux";
import { SelectConversation } from "../redux/slices/app";
import {
  SetConversationRead,
  SetCurrentConversation,
  SetCurrentGroup,
  SetGroupConversationRead,
} from "../redux/slices/conversation";
import { useEffect, useState } from "react";
import { convertToIST } from "../utils/formatTime";

const truncate = (value, length) => value?.length > length ? `${value.slice(0, length)}...` : value;

const ChatElement = ({ id, name, img, online, pinned, typing, chat_type = "individual" }) => {
  const userId = window.localStorage.getItem("user_id");
  const theme = useTheme();
  const dispatch = useDispatch();
  const { room_id } = useSelector((state) => state.app);
  const { direct_chat, group_chat } = useSelector((state) => state.conversation);
  const [meta, setMeta] = useState({ message: "", time: "", unread: 0 });
  const selected = room_id === id;
  const group = chat_type === "group";

  useEffect(() => {
    const rooms = group ? group_chat.messages : direct_chat.messages;
    const conversation = rooms.find((item) => item.id === id);
    setMeta({
      message: conversation?.last_message || "No messages yet",
      time: conversation?.last_message_time ? convertToIST(conversation.last_message_time) : "",
      unread: conversation?.unread || 0,
    });
  }, [direct_chat.messages, group, group_chat.messages, id]);

  const selectConversation = () => {
    dispatch(SelectConversation({ room_id: id, chat_type }));
    if (group) {
      dispatch(SetCurrentGroup({ room_id: id }));
      dispatch(SetGroupConversationRead({ room_id: id }));
    } else {
      dispatch(SetCurrentConversation({ room_id: id }));
      dispatch(SetConversationRead({ room_id: id, user_id: userId }));
    }
  };

  return (
    <Box
      role="button"
      tabIndex={0}
      aria-label={`Open ${name || "conversation"}`}
      aria-current={selected ? "true" : undefined}
      onClick={selectConversation}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          selectConversation();
        }
      }}
      sx={{
        position: "relative",
        borderRadius: "18px",
        border: `1px solid ${selected ? alpha(theme.palette.primary.main, 0.18) : "transparent"}`,
        bgcolor: selected ? alpha(theme.palette.primary.main, theme.palette.mode === "light" ? 0.1 : 0.14) : "transparent",
        cursor: "pointer",
        transition: "background-color 160ms ease, border-color 160ms ease, transform 160ms ease",
        "&:hover": { bgcolor: selected ? undefined : alpha(theme.palette.text.primary, 0.045), transform: "translateX(2px)" },
        "&:active": { transform: "scale(.99)" },
      }}
      p={1.5}
    >
      <Stack direction="row" alignItems="center" spacing={1.5}>
        <Box sx={{ position: "relative", flexShrink: 0 }}>
          <Avatar src={img} alt={name} sx={{ width: 50, height: 50, bgcolor: alpha(theme.palette.primary.main, 0.14), color: "primary.main" }}>
            {group ? <UsersThree size={22} /> : name?.charAt(0)?.toUpperCase()}
          </Avatar>
          {online && !group && (
            <Box sx={{ position: "absolute", right: 0, bottom: 1, width: 13, height: 13, borderRadius: "50%", bgcolor: "success.main", border: `3px solid ${theme.palette.background.paper}` }} />
          )}
        </Box>

        <Stack minWidth={0} flex={1} spacing={0.4}>
          <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={1}>
            <Typography variant="subtitle2" noWrap sx={{ color: "text.primary", fontWeight: meta.unread ? 800 : 700 }}>
              {name || "Unknown"}
            </Typography>
            <Typography variant="caption" sx={{ color: meta.unread ? "primary.main" : "text.secondary", fontSize: 10.5, flexShrink: 0 }}>
              {meta.time}
            </Typography>
          </Stack>
          <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={1}>
            <Stack direction="row" alignItems="center" spacing={0.5} minWidth={0}>
              {!meta.unread && meta.message !== "No messages yet" && <Check size={13} color={theme.palette.text.secondary} />}
              <Typography
                variant="caption"
                noWrap
                sx={{ color: typing ? "primary.main" : "text.secondary", fontWeight: typing ? 700 : 500 }}
              >
                {typing ? "typing..." : truncate(meta.message, 34)}
              </Typography>
            </Stack>
            <Stack direction="row" alignItems="center" spacing={0.75} flexShrink={0}>
              {pinned && <PushPin size={13} weight="fill" color={theme.palette.text.secondary} />}
              {meta.unread > 0 && (
                <Box sx={{ minWidth: 20, height: 20, px: 0.65, borderRadius: 10, display: "grid", placeItems: "center", bgcolor: "primary.main", color: "white", boxShadow: "0 5px 12px rgba(79,124,255,.28)" }}>
                  <Typography sx={{ fontSize: 10, fontWeight: 800 }}>{meta.unread > 99 ? "99+" : meta.unread}</Typography>
                </Box>
              )}
            </Stack>
          </Stack>
        </Stack>
      </Stack>
    </Box>
  );
};

export default ChatElement;
