import React, { useEffect, useMemo, useState } from "react";
import { Box, IconButton, Stack, Typography, Button, Tooltip } from "@mui/material";
import { MagnifyingGlass, Plus, SlidersHorizontal, Sparkle } from "phosphor-react";
import { alpha, useTheme } from "@mui/material/styles";
import { Search, SearchIconWrapper, StyledInputBase } from "../../components/Search";
import ChatElement from "../../components/ChatElement";
import Friends from "../../sections/main/Friends";
import { useDispatch, useSelector } from "react-redux";
import { FetchDirectConversations } from "../../redux/slices/conversation";
import useResponsive from "../../hooks/useResponsive";
import BottomNav from "../../layouts/dashboard/BottomNav";

const filters = ["All", "Unread", "Online"];

const Chats = () => {
  const isDesktop = useResponsive("up", "md");
  const dispatch = useDispatch();
  const theme = useTheme();
  const [openDialog, setOpenDialog] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [filter, setFilter] = useState("All");
  const { conversations } = useSelector((state) => state.conversation.direct_chat);

  useEffect(() => {
    dispatch(FetchDirectConversations());
  }, [dispatch]);

  const filteredConversations = useMemo(() => {
    const query = searchTerm.trim().toLowerCase();
    return (conversations || []).filter((item) => {
      const matchesSearch = !query || (item.name || "").toLowerCase().includes(query);
      const matchesFilter = filter === "All" || (filter === "Unread" ? item.unread > 0 : item.online);
      return matchesSearch && matchesFilter;
    });
  }, [conversations, filter, searchTerm]);

  return (
    <>
      <Box
        component="aside"
        sx={{
          position: "relative",
          zIndex: 3,
          height: "100vh",
          width: isDesktop ? 368 : "100vw",
          flexShrink: 0,
          bgcolor: alpha(theme.palette.background.paper, 0.84),
          backdropFilter: "blur(22px)",
          borderRight: isDesktop ? `1px solid ${alpha(theme.palette.text.primary, 0.08)}` : 0,
        }}
      >
        {!isDesktop && <BottomNav />}
        <Stack height="100%" sx={{ pb: isDesktop ? 0 : 11 }}>
          <Stack px={3} pt={3} pb={2.25} spacing={2.25}>
            <Stack direction="row" alignItems="center" justifyContent="space-between">
              <Stack spacing={0.25}>
                <Typography variant="h4" sx={{ fontSize: 26 }}>Messages</Typography>
                <Typography variant="caption" color="text.secondary">
                  {conversations.length} conversations
                </Typography>
              </Stack>
              <Tooltip title="Start a conversation">
                <IconButton
                  aria-label="Start a conversation"
                  onClick={() => setOpenDialog(true)}
                  sx={{ width: 44, height: 44, color: "white", background: "linear-gradient(135deg, #5C86FF, #4F70E8)", boxShadow: "0 9px 22px rgba(79,124,255,.28)", "&:hover": { background: "linear-gradient(135deg, #668EFF, #4F70E8)" } }}
                >
                  <Plus size={20} weight="bold" />
                </IconButton>
              </Tooltip>
            </Stack>

            <Search sx={{ height: 48, borderRadius: "15px", bgcolor: alpha(theme.palette.text.primary, 0.045), border: `1px solid ${alpha(theme.palette.text.primary, 0.07)}` }}>
              <SearchIconWrapper><MagnifyingGlass size={19} color={theme.palette.text.secondary} /></SearchIconWrapper>
              <StyledInputBase
                placeholder="Search conversations"
                inputProps={{ "aria-label": "Search conversations" }}
                value={searchTerm}
                onChange={(event) => setSearchTerm(event.target.value)}
              />
              <SlidersHorizontal size={18} color={theme.palette.text.secondary} style={{ marginRight: 14 }} />
            </Search>

            <Stack direction="row" spacing={1}>
              {filters.map((item) => (
                <Button
                  key={item}
                  size="small"
                  onClick={() => setFilter(item)}
                  variant={filter === item ? "contained" : "text"}
                  sx={{ minHeight: 34, px: 1.75, borderRadius: "11px", color: filter === item ? "white" : "text.secondary", bgcolor: filter === item ? undefined : alpha(theme.palette.text.primary, 0.035) }}
                >
                  {item}
                </Button>
              ))}
            </Stack>
          </Stack>

          <Stack px={2} pb={2} spacing={0.4} sx={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
            {filteredConversations.length ? filteredConversations.map((item) => (
              <ChatElement key={item.id} {...item} />
            )) : (
              <Stack alignItems="center" justifyContent="center" spacing={1.5} sx={{ flex: 1, px: 4, textAlign: "center" }}>
                <Box sx={{ width: 58, height: 58, borderRadius: "20px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.1) }}>
                  <Sparkle size={25} />
                </Box>
                <Typography variant="subtitle2">No conversations found</Typography>
                <Typography variant="caption" color="text.secondary">
                  {searchTerm ? "Try another search term." : "Start a new conversation and say hello."}
                </Typography>
              </Stack>
            )}
          </Stack>
        </Stack>
      </Box>
      {openDialog && <Friends open={openDialog} handleClose={() => setOpenDialog(false)} />}
    </>
  );
};

export default Chats;
