import { Dialog, DialogContent, Stack, Tab, Tabs } from '@mui/material';
import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { FetchAllUsers, FetchFriendRequests, FetchFriends, FetchUsers } from '../../redux/slices/app';
import { FriendElement, FriendRequestElement, UserElement } from '../../components/UserElement';
import { Search, SearchIconWrapper, StyledInputBase } from '../../components/Search';
import { MagnifyingGlass } from 'phosphor-react';
import { useTheme } from '@mui/material/styles';


const UsersList = () => {
    const dispatch = useDispatch();

    useEffect(() => {
        dispatch(FetchUsers());
    }, [dispatch]);

    const { users } = useSelector((state) => state.app);
    return (
        <>
            {users?.map((el, index) => {
                // Render user component here
                return <UserElement key={el.user.id} {...el} />
            })}
        </>
    )
}

const FriendsList = ({ handleClose }) => {
    const dispatch = useDispatch();

    useEffect(() => {
        dispatch(FetchFriends());
    }, []);

    const { friends } = useSelector((state) => state.app);
    return (
        <>
            {friends?.map((el, index) => {
                // Render friend component here
                return <FriendElement handleClose={handleClose} key={el.id} {...el} />
            })}
        </>
    )
}

const FriendRequestList = () => {
    const dispatch = useDispatch();

    useEffect(() => {
        dispatch(FetchFriendRequests());
    }, []);

    const { friendRequests } = useSelector((state) => state.app);
    return (
        <>
            {friendRequests?.map((el, index) => {
                // Render friend request component here
                return <FriendRequestElement key={el.id} {...el} />
            })}
        </>
    )
}

const Friends = ({ open, handleClose }) => {
    const theme = useTheme();
    const [value, setValue] = useState(0);

    const handleChange = (event, newValue) => {
        setValue(newValue);
    }
    return (
        <>
            <Dialog fullWidth maxWidth="xs" open={open} keepMounted onClose={handleClose} sx={{ p: 4, }} >
                <Stack sx={{ backgroundColor: theme.palette.mode === "light" ? "#F8FAFF" : theme.palette.background.default, overflowY: "hidden" }}>
                    <Stack>
                        <Stack p={2} sx={{ width: "100%" }}>
                            <Tabs value={value} onChange={handleChange} centered>
                                <Tab label="Explore" />
                                <Tab label="Friends" />
                                <Tab label="Requests" />
                            </Tabs>
                        </Stack>
                        <Stack px={4} pb={1.5}>
                            <Search>
                                <SearchIconWrapper>
                                    <MagnifyingGlass color="#709CE6" />
                                </SearchIconWrapper>
                                <StyledInputBase
                                    placeholder="Search…"
                                    inputProps={{ "aria-label": "search" }}
                                />
                            </Search>
                        </Stack>
                    </Stack>

                    <DialogContent>
                        <Stack sx={{ height: "100%" }}>
                            <Stack spacing={2.4}>
                                {(() => {
                                    switch (value) {
                                        case 0:
                                            //Display all users
                                            return <UsersList />;
                                        case 1:
                                            //Display all friends
                                            return <FriendsList handleClose={handleClose} />;
                                        case 2:
                                            //Display all requests
                                            return <FriendRequestList />;
                                    }
                                })()}
                            </Stack>
                        </Stack>
                    </DialogContent>
                </Stack>
            </Dialog>
        </>
    )
}

export default Friends;